insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'quran-introduction','An Introduction to the Qur’an','A concise introduction to the Qur’an, its central themes, structure, and place in Muslim belief.','["The Qur’an is the revelation Muslims believe Allah sent to Prophet Muhammad ﷺ. Muslims recite it in worship, study its guidance, and seek to live by its teachings.","The Qur’an is arranged into 114 surahs (chapters). Surahs contain ayat (verses), and the text addresses faith, worship, character, accountability, mercy, justice, and guidance for human life.","This overview is introductory. Detailed explanations of individual verses should be studied alongside recognized tafsir works and qualified scholarship, with context considered."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='quran' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'five-pillars-overview','The Five Pillars of Islam','The five foundational practices commonly described as the pillars of Islam.','["The Five Pillars are the testimony of faith (shahadah), prayer (salah), zakat, fasting Ramadan (sawm), and pilgrimage to Makkah (hajj) for those able.","They are foundational acts of worship and practice. Their details, conditions, and exemptions are explained in fiqh, and some details differ among recognized schools of Islamic law.","The well-known narration describing Islam’s five pillars is reported in Sahih al-Bukhari and Sahih Muslim."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='aqeedah' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'hadith-what-is-hadith','What Is Hadith?','What hadith reports are, how they relate to the Sunnah, and why their evaluation matters.','["Hadith reports describe statements, actions, approvals, and characteristics attributed to Prophet Muhammad ﷺ. Scholars examine their chains of transmission (isnad) and wording (matn), along with other relevant evidence.","Hadith classification is a scholarly discipline. Terms such as sahih, hasan, da‘if, and mawdu‘ have technical meanings, and a report’s grading should be attributed to the scholar or source giving that assessment.","Hadith references can vary by edition and numbering system. When possible, cite the collection, book or chapter, narrator, and a numbering reference while noting the edition or grading source."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='hadith' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'prophet-adam-introduction','Adam عليه السلام: The First Human','An introductory account of Adam in the Qur’an, focusing on creation, learning, repentance, and human responsibility.','["The Qur’an describes Adam as the first human and recounts Allah teaching him, the command concerning the angels, the test in the Garden, and his and his wife’s repentance.","The Qur’anic narrative emphasizes human dignity, knowledge, responsibility, the danger of disobedience, and the openness of repentance. The Qur’an does not require Muslims to rely on every later detail found in popular storytelling.","For study, compare the passages in their Qur’anic context and consult tafsir for explanations. Details not established by the Qur’an or reliable reports should be treated cautiously."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='prophets' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'prophet-nuh-introduction','Nuh عليه السلام: Patience in Calling to Faith','The Qur’anic account of Prophet Nuh’s long دعوت, perseverance, and the lessons of his people’s response.','["Nuh is presented in the Qur’an as a messenger who called his people to worship Allah alone and persisted despite rejection.","The Qur’an highlights his patience, sincere calling, and reliance upon Allah. His story is repeated across surahs with different emphases, so each passage should be read in its own context.","The Qur’an gives a duration of 950 years for his calling among his people (Qur’an 29:14)."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='prophets' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'prophet-ibrahim-introduction','Ibrahim عليه السلام: Faith and Devotion','Themes in the Qur’anic portrayal of Ibrahim: sincere faith, reflection, hospitality, and submission to Allah.','["Ibrahim is a central prophet in the Qur’an, associated with sincere devotion to Allah, rejection of idolatry, reflection upon creation, and trust in Allah.","The Qur’an recounts his prayers, his family, the rebuilding of the Ka‘bah with Isma‘il, and his role in the legacy of monotheistic worship.","Muslims are taught to honor Ibrahim and his family. Study the relevant passages with tafsir rather than relying on unverified narrative additions."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='prophets' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'seerah-makkah-period-overview','The Makkan Period of the Seerah','An overview of the early mission in Makkah, the message of tawhid, and the community’s perseverance.','["The Makkan period of Prophet Muhammad’s ﷺ mission centered on calling people to worship Allah alone, moral accountability, and the coming of the Hereafter.","Early Muslims faced opposition and hardship. The Qur’anic revelations of this period often emphasize faith, patience, mercy, the signs of Allah, and the stories of earlier messengers.","Chronological details in Seerah literature sometimes differ. This article is a broad overview; specific dates and reports should be checked against recognized Seerah sources."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='seerah' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'seerah-hijrah-overview','The Hijrah: Migration to Madinah','Why the migration to Madinah was a turning point for the early Muslim community.','["The Hijrah refers to the migration of Prophet Muhammad ﷺ and early Muslims from Makkah to Madinah. It marked a major turning point in the history of the Muslim community.","The Qur’an refers to the migration and praises those who left their homes for Allah’s sake. The event is also associated with the beginning of the Hijri calendar era.","Narrative details are best studied through the Qur’an and reliable Seerah and hadith sources. The Hijrah is remembered for faith, sacrifice, brotherhood, planning, and reliance upon Allah."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='seerah' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'salah-introduction','Salah: An Introduction to the Daily Prayer','The importance of prayer in Islam and a high-level introduction to its daily practice.','["Salah is a central act of worship in Islam. Muslims perform five obligatory daily prayers at prescribed times, with prayer involving recitation, standing, bowing, prostration, and remembrance.","The Qur’an repeatedly commands establishing prayer. Practical details such as prerequisites, prayer times, and certain movements are explained through the Sunnah and fiqh.","There are recognized differences in some details of prayer among Islamic legal schools. This introductory article is not a substitute for a detailed guide from a trusted teacher or school."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='fiqh' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'ramadan-introduction','Ramadan and Fasting','An introduction to fasting Ramadan, its purpose, and the Qur’anic basis for the obligation.','["Fasting Ramadan is an act of worship prescribed for Muslims. The Qur’an explains that fasting was prescribed so that believers may develop taqwa (God-consciousness).","The obligation and core guidance are found in Surah al-Baqarah. Islamic law also discusses exemptions, missed fasts, and circumstances in which a person should seek qualified guidance.","Fasting is not only abstaining from food and drink; Islamic teachings also emphasize conduct, sincerity, patience, and avoiding wrongdoing."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='fiqh' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'companions-abu-bakr-introduction','Abu Bakr رضي الله عنه: An Introduction','An introductory overview of Abu Bakr’s place among the Companions and his role in early Muslim history.','["Abu Bakr رضي الله عنه was a close Companion of Prophet Muhammad ﷺ and the first caliph after the Prophet’s death according to the historical account accepted by Sunni tradition.","He is remembered for his companionship, support of the Prophet, and leadership during the early community’s difficult period. His biography should be studied through reliable historical and hadith sources.","This short introduction avoids disputed or weakly sourced details; a fuller biography should cite individual reports and note differences in historical transmission."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='companions' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
insert into public.ie_articles(slug,title,summary,content,category_id,status,author_name,tags,published_at) select 'islamic-ethics-truthfulness','Truthfulness in Islam','The Qur’anic and Prophetic emphasis on honesty, truthful speech, and integrity.','["Truthfulness is a major Islamic virtue. The Qur’an commands believers to be mindful of Allah and to speak words that are straight and truthful.","Prophetic teachings connect truthfulness with righteousness and warn against habitual lying. Honesty includes speech, promises, testimony, dealings, and the way information is shared.","A practical application is to verify information before repeating it, avoid exaggeration, fulfill commitments, and correct mistakes honestly."]'::jsonb,c.id,'review','Mifask Editorial Team',array['starter','editorial-review'],null from public.ie_categories c where c.slug='muslim-life' on conflict (slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,category_id=excluded.category_id,status='review',updated_at=now();
